    (1822::bigint, jsonb_build_object(
      'queue_wait','This is a conventional three-star hotel: pressure comes at afternoon check-in, breakfast and trade-fair weekends rather than a nightlife door. Reserve parking before arrival because the central Belgian Quarter location makes spaces valuable. Pride and Carnival dates warrant early room booking.','best_nights','Use the hotel as a practical base for Rudolfplatz, the Belgian Quarter and nearby queer bars. Friday and Saturday put the liveliest streets within walking distance; a weekday is calmer and often better value. The property does not run a verified queer nightlife programme of its own.','crowd_mix','City-break couples, business travellers, tour groups and event visitors make up the mainstream international mix. LGBTQ+ guests benefit from proximity to Cologne’s scene but are not a distinct in-house crowd. Trade fairs and Carnival can change the lobby balance dramatically.','dress_code','Ordinary city-hotel casual is right. There is no published fashion gate; bring a rain layer and comfortable shoes for the short walks to Rudolfplatz and Schaafenstraße. Breakfast and reception remain informal, while nearby nightlife venues set their own entry expectations.','staff_inclusivity','Verified reviews commonly value the location, breakfast and helpful reception, with some complaints about dated rooms, noise or inconsistent comfort. No dedicated LGBTQ+ training evidence surfaced. The central setting is relevant, but couples should still state bedding and access needs clearly.','venue_classification','active_mainstream_three_star_central_cologne_hotel_near_belgian_quarter_rudolfplatz_and_queer_nightlife_with_business_citybreak_group_mix_practical_location_breakfast_and_mixed_room_age_comfort_consensus','identity_note','Hotel Flandrischer Hof is a mainstream hotel near Cologne’s queer nightlife, not an LGBTQ+-specific property. Its relevance is location rather than dedicated programming.','source_urls',to_jsonb(array['https://www.flandrischerhof.de/','https://www.booking.com/reviews/de/hotel/hotelflandrischerhofcol.en-gb.html','https://www.tripadvisor.com/Hotel_Review-g187371-d202278-Reviews-Hotel_Flandrischer_Hof-Cologne_North_Rhine_Westphalia.html']::text[]),
      'topic_evidence',jsonb_build_object(
        'queue_wait',jsonb_build_object('status','standard_afternoon_checkin_breakfast_parking_and_major_event_booking_pressure_without_nightlife_door','source_urls',to_jsonb(array['https://www.flandrischerhof.de/','https://www.booking.com/reviews/de/hotel/hotelflandrischerhofcol.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'best_nights',jsonb_build_object('status','weekend_nearby_scene_access_and_quieter_weekday_value_without_property_queer_programme','source_urls',to_jsonb(array['https://www.flandrischerhof.de/','https://www.tripadvisor.com/Hotel_Review-g187371-d202278-Reviews-Hotel_Flandrischer_Hof-Cologne_North_Rhine_Westphalia.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'crowd_mix',jsonb_build_object('status','mainstream_couple_business_group_event_and_lgbtq_city_guest_mix_driven_by_calendar','source_urls',to_jsonb(array['https://www.booking.com/reviews/de/hotel/hotelflandrischerhofcol.en-gb.html','https://www.flandrischerhof.de/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code',jsonb_build_object('status','informal_city_hotel_clothing_with_weather_walking_and_offsite_venue_rule_practicality','source_urls',to_jsonb(array['https://www.flandrischerhof.de/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity',jsonb_build_object('status','helpful_reception_location_and_breakfast_praise_with_dated_noise_comfort_caveats_and_no_verified_lgbtq_training','source_urls',to_jsonb(array['https://www.booking.com/reviews/de/hotel/hotelflandrischerhofcol.en-gb.html','https://www.tripadvisor.com/Hotel_Review-g187371-d202278-Reviews-Hotel_Flandrischer_Hof-Cologne_North_Rhine_Westphalia.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
      ),'research_status','editorial_review_consensus','updated_at','2026-08-07T00:00:00Z'
    )),
    (1825::bigint, jsonb_build_object(
      'queue_wait','Self-service elements keep arrival moving, but mid-afternoon check-in and the rooftop bar can bunch on busy weekends. Reserve NENI if dinner matters and ask for a quiet room before arrival. Trade fairs, Pride and Carnival sell the building early, so room availability is the real queue.','best_nights','A clear evening suits rooftop drinks and skyline views; Friday and Saturday bring more local energy, while Sunday or a weekday reveals the design without as much bustle. The hotel is close enough to queer nightlife for an easy night out, but its own programme is mainstream and event-led.','crowd_mix','Design-minded city-break couples, business travellers, creatives, groups and international visitors dominate. Locals join at the restaurant, café and rooftop. LGBTQ+ guests fit comfortably into the playful mainstream mix, though this is not a queer hotel and conventions can reshape the crowd.','dress_code','Playful smart casual suits the retro-futurist interiors: trainers, bold colour, denim and a sharper rooftop layer all work. There is no formal gate. Rooms and public spaces favour style over convention; bring weather protection for the terrace and read the restaurant booking terms.','staff_inclusivity','Reviews frequently praise friendly teams, location, breakfast and memorable design, while housekeeping consistency, noise and value draw some criticism. No dedicated LGBTQ+ training statement was verified. Expect relaxed professional hospitality, and put room, bedding or privacy requests in writing.','venue_classification','active_25hours_the_circle_design_hotel_in_cologne_altstadt_nord_with_retro_futurist_rooms_neni_restaurant_rooftop_bar_sauna_design_business_leisure_local_dining_mix_and_generally_positive_service_consensus','identity_note','The stored “Hotel The Circle” is the active 25hours Hotel The Circle in Cologne. It is a mainstream design hotel, not an LGBTQ+-specific property.','source_urls',to_jsonb(array['https://25hours-hotels.com/cologne/the-circle/','https://www.booking.com/reviews/de/hotel/25hours-the-circle.en-gb.html','https://www.tripadvisor.com/Hotel_Review-g187371-d13372326-Reviews-25hours_Hotel_The_Circle-Cologne_North_Rhine_Westphalia.html']::text[]),
      'topic_evidence',jsonb_build_object(
        'queue_wait',jsonb_build_object('status','midafternoon_checkin_rooftop_restaurant_and_major_city_event_capacity_with_advance_room_booking_need','source_urls',to_jsonb(array['https://25hours-hotels.com/cologne/the-circle/','https://www.booking.com/reviews/de/hotel/25hours-the-circle.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
