        'crowd_mix',jsonb_build_object('status','design_citybreak_business_creative_group_international_guest_and_local_restaurant_rooftop_mix','source_urls',to_jsonb(array['https://25hours-hotels.com/cologne/the-circle/','https://www.booking.com/reviews/de/hotel/25hours-the-circle.en-gb.html']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'dress_code',jsonb_build_object('status','playful_smart_casual_without_formal_gate_and_rooftop_weather_practicality','source_urls',to_jsonb(array['https://25hours-hotels.com/cologne/the-circle/']::text[]),'checked_at','2026-08-07T00:00:00Z'),
        'staff_inclusivity',jsonb_build_object('status','friendly_design_location_breakfast_praise_with_housekeeping_noise_value_caveats_and_no_specific_lgbtq_training','source_urls',to_jsonb(array['https://www.booking.com/reviews/de/hotel/25hours-the-circle.en-gb.html','https://www.tripadvisor.com/Hotel_Review-g187371-d13372326-Reviews-25hours_Hotel_The_Circle-Cologne_North_Rhine_Westphalia.html']::text[]),'checked_at','2026-08-07T00:00:00Z')
      ),'research_status','editorial_review_consensus','updated_at','2026-08-07T00:00:00Z'
    ))
)
update public.places as p
set venue_intel = coalesce(p.venue_intel, '{}'::jsonb) || reviewed.patch
from reviewed
where p.id = reviewed.id;

update public.places
set seo_indexable = false,
    seo_quality_status = 'rejected'
where id in (1828,243);

do $$
declare updated_count integer;
begin
  select count(*) into updated_count from public.places
  where id in (237,1828,243,236,1826,239,1822,1825)
    and venue_intel->>'research_status' = 'editorial_review_consensus'
    and venue_intel->>'updated_at' = '2026-08-07T00:00:00Z';
  if updated_count <> 8 then raise exception 'Expected 8 globally reviewed venue rows, found %', updated_count; end if;
end $$;

commit;
